; march.asm -- chapter 26: two pattern tables
; generated by gen26.py
        INCLUDE "msx.inc"
        OUTPUT "march.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; herd.asm's 32 figures, standing, all with pattern 112. The pattern table at
; $3800 has one figure there, the one at $1800 another: patterns 112 on are past
; the names and the attributes. Every 8 frames R#6 changes table.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 168
        otir
        VRAM_WRITE $3B80        ; pattern 112 of the table at $3800
        ld hl, pose1
        ld c, VDP_DATA
        ld b, 32
        otir
        VRAM_WRITE $1B80        ; pattern 112 of the table at $1800
        ld hl, pose2
        ld b, 32
        otir
        VRAM_WRITE $1B00        ; the attributes
        ld hl, atts
        ld c, VDP_DATA
        ld b, 128
        otir
        VDP_REG 1, $C2          ; the display on, sprites of 16 x 16
        in a, (VDP_CTRL)        ; F cleared: the first wait is for a whole paper
        ld b, 8
w0:     call frame
        djnz w0
s0:     VDP_REG 6, $03          ; the patterns at $1800
e0:     ld b, 8
w1:     call frame
        djnz w1
s1:     VDP_REG 6, $07          ; the patterns at $3800
e1:     ld b, 8
w2:     call frame
        djnz w2
s2:     VDP_REG 6, $03          ; the patterns at $1800
e2:     ld b, 8
w3:     call frame
        djnz w3
s3:     VDP_REG 6, $07          ; the patterns at $3800
e3:
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $3C, $66, $6E, $76, $66, $66, $3C, $00
        db $18, $38, $18, $18, $18, $18, $7E, $00
        db $3C, $66, $06, $0C, $30, $60, $7E, $00
        db $3C, $66, $06, $1C, $06, $66, $3C, $00
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $00, $0F, $1F, $3F, $7C, $78, $70, $70
        db $70, $70, $78, $7C, $3F, $1F, $0F, $00
        db $00, $F0, $F8, $FC, $3E, $1E, $0E, $0E
        db $0E, $0E, $1E, $3E, $FC, $F8, $F0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $F8, $F0, $F8, $DC, $8E, $07, $03, $01
atts:
        db $06, $00, $70, $01
        db $06, $40, $70, $04
        db $06, $80, $70, $01
        db $06, $C0, $70, $04
        db $1D, $10, $70, $04
        db $1D, $50, $70, $01
        db $1D, $90, $70, $04
        db $1D, $D0, $70, $01
        db $34, $20, $70, $01
        db $34, $60, $70, $04
        db $34, $A0, $70, $01
        db $34, $E0, $70, $04
        db $4B, $30, $70, $04
        db $4B, $70, $70, $01
        db $4B, $B0, $70, $04
        db $4B, $F0, $70, $01
        db $62, $40, $70, $01
        db $62, $80, $70, $04
        db $62, $C0, $70, $01
        db $62, $00, $70, $04
        db $79, $50, $70, $04
        db $79, $90, $70, $01
        db $79, $D0, $70, $04
        db $79, $10, $70, $01
        db $90, $60, $70, $01
        db $90, $A0, $70, $04
        db $90, $E0, $70, $01
        db $90, $20, $70, $04
        db $A7, $70, $70, $04
        db $A7, $B0, $70, $01
        db $A7, $F0, $70, $04
        db $A7, $30, $70, $01
pose1:
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
pose2:
        db $33, $37, $35, $37, $32, $1F, $07, $07
        db $07, $07, $07, $0C, $18, $30, $70, $70
        db $CC, $EC, $AC, $EC, $4C, $F8, $E0, $E0
        db $E0, $E0, $E0, $30, $18, $0C, $0E, $0E
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
